hints.code_snippet:
class Formatter {
  format(msg) { return `[LOG]: ${msg}`; }
}
class Transport {
  send(payload) { return true; }
}

class LogService {
  constructor(formatter, transport) {
    this.formatter = formatter;
    this.transport = transport;
    this.logRecords = []; 
  }

  log(message) {
    const formattedMessage = this.formatter.format(message);
    this.logRecords.push(formattedMessage);
    return this.transport.send(formattedMessage);
  }

  getSentLogCount() {
    return this.logRecords.length;
  }
}

class App {
  constructor(formatter, transport) {
    this.formatter = formatter;
    this.transport = transport;
    this.logger = new LogService(this.formatter, this.transport);
  }

  processData(data) {
    this.logger.log(`Processing item: ${data}`);
    if (data === "error") {
      this.logger.log("An error condition was met.");
    }
    return `Processed ${this.logger.getSentLogCount()} logs related to data processing.`;
  }
}

